/* A page-table entry once memory can be overcommitted. The present bit
   is the whole trick: one bit that says "this page is not in RAM". */
typedef struct {
    unsigned pfn      : 20;   /* frame number - OR a swap slot, see below */
    unsigned present  : 1;    /* 1 = in a frame, 0 = on disk */
    unsigned valid    : 1;    /* 1 = this page belongs to the address space */
    unsigned dirty    : 1;    /* written since it was paged in */
    unsigned reference: 1;    /* touched since the OS last cleared this */
    unsigned writable : 1;
} pte_t;

/* Hardware raises a page fault; this runs in the kernel, on the CPU that
   faulted, with the faulting instruction not yet retired. */
void handle_page_fault(unsigned va)
{
    pte_t *pte = walk(current->page_dir, va);

    if (!pte->valid)
        return kill_with(SIGSEGV);        /* never mapped: a real bug */

    unsigned frame = get_free_frame();    /* may run the replacement policy */
    swap_in(pte->pfn, frame);             /* BLOCKS - milliseconds of disk */

    pte->pfn     = frame;
    pte->present = 1;
    tlb_insert(va >> 12, frame);
    retry_instruction();                  /* start over; now it succeeds */
}

/* FIFO replacement: a queue of resident pages, evict from the head.
   No bookkeeping on a hit at all - which is exactly its problem. */
int fifo_fault(int page)
{
    if (resident(page))
        return 0;                          /* hit: the queue does not move */

    if (queue_full())
        evict(dequeue());                  /* oldest arrival, however hot */
    enqueue(page);
    return 1;                              /* one fault */
}

/* Reference string 1 2 3 4 1 2 5 1 2 3 4 5
     3 frames -> 9 faults
     4 frames -> 10 faults      <- more memory, MORE faults
   That is Belady's anomaly, and FIFO really does exhibit it. */

/* Clock: LRU's reference bit, sampled by a rotating hand.
   The bit is set by hardware on every access and cleared only here. */
unsigned hand;                    /* the only state the policy keeps */

int clock_evict(void)
{
    for (;;) {
        if (frames[hand].reference == 0) {   /* not touched since last sweep */
            int victim = hand;
            hand = (hand + 1) % NFRAMES;
            return victim;
        }
        frames[hand].reference = 0;          /* second chance, then move on */
        hand = (hand + 1) % NFRAMES;
    }
}

/* Refinement: prefer a clean victim. Evicting a dirty page costs a write
   to swap before the read the fault was waiting for - two I/Os, not one -
   so a sweep may skip dirty pages and let a background thread write them
   back, turning them clean before the hand comes round again. */

/* Thrashing is not a bug in the replacement policy. It is the policy
   working correctly on a machine that is simply too small. */

/* Working set: the distinct pages referenced in the last D references. */
int working_set_size(int *refs, int t, int D)
{
    int seen[NPAGES] = {0}, n = 0;
    for (int i = (t - D + 1 > 0 ? t - D + 1 : 0); i <= t; i++)
        if (!seen[refs[i]]++) n++;
    return n;
}

/* Admission control: if the working sets do not fit, do not run them all. */
void balance(void)
{
    int demand = 0;
    for (proc_t *p = runnable; p; p = p->next)
        demand += p->ws_size;

    while (demand > NFRAMES)                 /* oversubscribed */
        demand -= suspend_one_process();     /* swap a whole process out */
}

/* Demand paging brings in one page per fault. Prefetching (clustering)
   reads neighbouring swap slots in the same request: nearly free once the
   arm has moved, wasted only if the guess is wrong. */

#include <pthread.h>
#include <stdio.h>

int counter = 0;                    /* one object, both threads see it */

void *worker(void *arg) {
    char *name = (char *) arg;
    int i;                          /* one copy per thread, on its stack */
    for (i = 0; i < 3; i++)
        counter = counter + 1;      /* the shared object, touched unguarded */
    printf("%s finished, counter reads %d\n", name, counter);
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, worker, "A");
    pthread_create(&t2, NULL, worker, "B");
    pthread_join(t1, NULL);         /* main blocks until t1 has returned */
    pthread_join(t2, NULL);
    printf("final: %d\n", counter); /* 6 if we are lucky; 2 to 6 in truth */
    return 0;
}

#include <pthread.h>

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int counter = 0;

void increment(void) {
    pthread_mutex_lock(&lock);      /* entry: at most one thread gets past */
    counter = counter + 1;          /* the critical section */
    pthread_mutex_unlock(&lock);    /* exit: hand the region to a waiter */
}

/* The kernel's first and most tempting answer, on a uniprocessor only. */
void increment_by_masking(void) {
    disable_interrupts();           /* no timer, so no context switch */
    counter = counter + 1;
    enable_interrupts();
}

/* What the hardware provides. On x86 this is one instruction (xchg);
   the C below only describes what it does - it is not an implementation. */
int TestAndSet(int *ptr, int new) {
    int old = *ptr;                 /* fetch the old value ...            */
    *ptr = new;                     /* ... and store the new one, as one  */
    return old;                     /*     indivisible step               */
}

typedef struct { int flag; } lock_t;

void init(lock_t *l)   { l->flag = 0; }
void lock(lock_t *l)   { while (TestAndSet(&l->flag, 1) == 1) ; /* spin */ }
void unlock(lock_t *l) { l->flag = 0; }

/* Compare-and-swap does the same job but reports what it found, so a
   thread can retry a whole update instead of only acquiring a lock. */
int CompareAndSwap(int *ptr, int expected, int new) {
    int actual = *ptr;
    if (actual == expected) *ptr = new;
    return actual;
}

void atomic_increment(int *v) {
    int old;
    do { old = *v; } while (CompareAndSwap(v, old, old + 1) != old);
}

int done = 0;
pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t  c = PTHREAD_COND_INITIALIZER;

void thr_exit(void) {
    pthread_mutex_lock(&m);
    done = 1;
    pthread_cond_signal(&c);
    pthread_mutex_unlock(&m);
}

void thr_join(void) {
    pthread_mutex_lock(&m);
    while (done == 0)
        pthread_cond_wait(&c, &m);
    pthread_mutex_unlock(&m);
}

int buffer[MAX];
int fill_ptr = 0, use_ptr = 0, count = 0;

pthread_mutex_t m     = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t  empty = PTHREAD_COND_INITIALIZER;   /* producers wait here */
pthread_cond_t  fill  = PTHREAD_COND_INITIALIZER;   /* consumers wait here */

void producer(int value) {
    pthread_mutex_lock(&m);
    while (count == MAX)
        pthread_cond_wait(&empty, &m);
    buffer[fill_ptr] = value;
    fill_ptr = (fill_ptr + 1) % MAX;
    count++;
    pthread_cond_signal(&fill);
    pthread_mutex_unlock(&m);
}

int consumer(void) {
    pthread_mutex_lock(&m);
    while (count == 0)
        pthread_cond_wait(&fill, &m);
    int value = buffer[use_ptr];
    use_ptr = (use_ptr + 1) % MAX;
    count--;
    pthread_cond_signal(&empty);
    pthread_mutex_unlock(&m);
    return value;
}

sem_t empty, full, mutex;

sem_init(&empty, 0, MAX);   /* MAX slots are free */
sem_init(&full,  0, 0);     /* nothing to consume yet */
sem_init(&mutex, 0, 1);     /* a binary semaphore used as a lock */

void put(int value) {
    sem_wait(&empty);
    sem_wait(&mutex);
    buffer[fill_ptr] = value;
    fill_ptr = (fill_ptr + 1) % MAX;
    sem_post(&mutex);
    sem_post(&full);
}

int get(void) {
    sem_wait(&full);
    sem_wait(&mutex);
    int value = buffer[use_ptr];
    use_ptr = (use_ptr + 1) % MAX;
    sem_post(&mutex);
    sem_post(&empty);
    return value;
}

void transfer(account_t *from, account_t *to, int amount) {
    pthread_mutex_lock(&from->lock);
    pthread_mutex_lock(&to->lock);        /* the circular wait lives here */
    from->balance -= amount;
    to->balance   += amount;
    pthread_mutex_unlock(&to->lock);
    pthread_mutex_unlock(&from->lock);
}

void transfer_ordered(account_t *from, account_t *to, int amount) {
    account_t *first  = (from < to) ? from : to;
    account_t *second = (from < to) ? to   : from;
    pthread_mutex_lock(&first->lock);
    pthread_mutex_lock(&second->lock);
    from->balance -= amount;
    to->balance   += amount;
    pthread_mutex_unlock(&second->lock);
    pthread_mutex_unlock(&first->lock);
}

