/* The device protocol: three registers and one loop. */
void disk_rw(struct buf *b, int write) {
    while (inb(DEV_STATUS) & BUSY)          /* 1. wait until idle */
        ;
    outdw(DEV_LBA, b->blockno);             /* 2. the parameters first */
    outb(DEV_COMMAND, write ? CMD_WRITE : CMD_READ);   /* 3. the trigger */

    if (write)
        outsl(DEV_DATA, b->data, BSIZE / 4);   /* 4a. PIO: the CPU copies */
    /* 4b. or dma_setup(b->data, BSIZE) before the command, and the engine
       moves the bytes instead, in either direction */

    while (inb(DEV_STATUS) & BUSY)          /* 5. wait for completion */
        ;
}

/* Disk D: average seek 4 ms, 15,000 RPM, one 4 KB block in 0.04 ms. */
#define SEEK_MS  4.0
#define ROT_MS   (60000.0 / 15000 / 2)   /* half a rotation = 2 ms */
#define XFER_MS  0.04

double scattered(int blocks) { return blocks * (SEEK_MS + ROT_MS + XFER_MS); }
double contiguous(int blocks) { return SEEK_MS + ROT_MS + blocks * XFER_MS; }

/* 256 blocks = 1 MB:  scattered 1546.24 ms,  contiguous 16.24 ms - 95x. */

struct dinode {              /* 128 bytes, one slot in the inode table */
    uint16 type;             /* regular file, directory, or symlink     */
    uint16 nlink;            /* how many directory entries point here   */
    uint32 size;
    uint32 addrs[12];        /* direct pointers: the first 48 KB        */
    uint32 indirect;         /* 1024 more blocks:            4 MB       */
    uint32 double_indirect;  /* 1024 x 1024 blocks:          4 GB       */
    uint32 triple_indirect;  /* 1024^3 blocks:               4 TB       */
};

struct dirent {              /* a directory is just a file of these     */
    uint32 inum;
    char   name[NAME_MAX];
};

